/* B"H */
#include "include/awts_native_browser.h"

static float sx(const AwtsBrowserState* s, int px) { return ((float)px / (float)s->width) * 2.0f - 1.0f; }
static float sy(const AwtsBrowserState* s, int py) { return 1.0f - ((float)py / (float)s->height) * 2.0f; }
static float sw(const AwtsBrowserState* s, int px) { return ((float)px / (float)s->width) * 2.0f; }
static float sh(const AwtsBrowserState* s, int py) { return ((float)py / (float)s->height) * 2.0f; }

static void awts_gl_rect(float x, float y, float w, float h, float r, float g, float b) {
  glColor3f(r, g, b);
  glBegin(GL_QUADS);
    glVertex2f(x, y);
    glVertex2f(x + w, y);
    glVertex2f(x + w, y + h);
    glVertex2f(x, y + h);
  glEnd();
}

static void awts_gl_outline(float x, float y, float w, float h, float r, float g, float b) {
  glColor3f(r, g, b);
  glBegin(GL_LINE_LOOP);
    glVertex2f(x, y);
    glVertex2f(x + w, y);
    glVertex2f(x + w, y + h);
    glVertex2f(x, y + h);
  glEnd();
}

static void awts_gl_triangle(float cx, float cy, float s, float pulse) {
  glBegin(GL_TRIANGLES);
    glColor3f(1.0f, 0.25f + pulse * 0.2f, 0.15f); glVertex2f(cx - s, cy - s * 0.72f);
    glColor3f(0.1f, 0.9f, 0.35f);                  glVertex2f(cx + s, cy - s * 0.72f);
    glColor3f(0.25f, 0.45f, 1.0f);                 glVertex2f(cx,     cy + s);
  glEnd();
}

static void awts_gl_bar(float x, float y, float w, float value, float r, float g, float b) {
  awts_gl_rect(x, y, w * value, 0.035f, r, g, b);
  awts_gl_outline(x, y, w, 0.035f, 0.35f, 0.42f, 0.55f);
}

void awts_font_init(AwtsBrowserState* state, HDC dc) {
  if (state->font.ready) return;
  state->font.base = glGenLists(256);
  state->font.font = CreateFontA(
    -16, 0, 0, 0, FW_NORMAL, FALSE, FALSE, FALSE,
    ANSI_CHARSET, OUT_TT_PRECIS, CLIP_DEFAULT_PRECIS,
    ANTIALIASED_QUALITY, FF_DONTCARE | DEFAULT_PITCH,
    "Consolas"
  );
  if (!state->font.font) {
    state->font.font = CreateFontA(-16, 0, 0, 0, FW_NORMAL, FALSE, FALSE, FALSE, ANSI_CHARSET, OUT_TT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, FF_DONTCARE | DEFAULT_PITCH, "Segoe UI");
  }
  SelectObject(dc, state->font.font);
  state->font.ready = wglUseFontBitmapsA(dc, 0, 255, state->font.base) ? 1 : 0;
}

void awts_font_destroy(AwtsBrowserState* state) {
  if (state->font.ready) glDeleteLists(state->font.base, 256);
  if (state->font.font) DeleteObject(state->font.font);
  state->font.ready = 0;
  state->font.font = NULL;
  state->font.base = 0;
}

void awts_draw_text(AwtsBrowserState* state, float x, float y, const char* text, float r, float g, float b) {
  if (!state->font.ready || !text) return;
  glColor3f(r, g, b);
  glRasterPos2f(x, y);
  glPushAttrib(GL_LIST_BIT);
  glListBase(state->font.base);
  glCallLists((GLsizei)strlen(text), GL_UNSIGNED_BYTE, text);
  glPopAttrib();
}

static void draw_address_text(AwtsBrowserState* state, float x, float y, float w) {
  char shown[160];
  snprintf(shown, sizeof(shown), "%s%s", state->url, state->focusedAddress && ((state->frames / 30) % 2 == 0) ? "|" : "");
  awts_draw_text(state, x + 0.012f, y + 0.030f, shown, 0.82f, 0.90f, 1.0f);
}

void awts_draw_native_browser(AwtsBrowserState* state) {
  float pulse = (float)((state->frames % 120) / 120.0f);
  state->pulse = pulse;
  glViewport(0, 0, state->width, state->height);
  glClearColor(0.012f, 0.016f + pulse * 0.035f, 0.035f, 1.0f);
  glClear(GL_COLOR_BUFFER_BIT);

  float chromeY = sy(state, 34);
  float chromeH = -sh(state, 72);
  awts_gl_rect(-0.96f, chromeY, 1.92f, chromeH, 0.045f, 0.055f, 0.085f);
  awts_gl_rect(-0.90f, sy(state, 56), 0.08f, -sh(state, 18), 0.95f, 0.25f, 0.22f);
  awts_gl_rect(-0.79f, sy(state, 56), 0.08f, -sh(state, 18), 0.95f, 0.72f, 0.18f);
  awts_gl_rect(-0.68f, sy(state, 56), 0.08f, -sh(state, 18), 0.18f, 0.82f, 0.35f);

  float ax = sx(state, 238), ay = sy(state, 77), aw = sw(state, 635), ah = -sh(state, 16);
  awts_gl_rect(ax, ay, aw, ah, state->hoverAddress ? 0.13f : 0.08f, 0.12f, 0.19f);
  awts_gl_outline(ax, ay, aw, ah, state->focusedAddress ? 0.60f : 0.30f, 0.70f, 1.0f);
  draw_address_text(state, ax, ay, aw);

  awts_draw_text(state, -0.90f, 0.745f, "B'H Merkava Browser", 0.78f, 0.90f, 1.0f);
  awts_draw_text(state, -0.90f, 0.690f, state->statusText, 0.55f, 0.95f, 0.68f);

  awts_gl_rect(-0.92f, -0.82f, 1.84f, 1.42f, 0.025f, 0.034f, 0.060f);
  awts_gl_outline(-0.92f, -0.82f, 1.84f, 1.42f, 0.20f, 0.34f, 0.58f);
  awts_draw_text(state, -0.84f, 0.515f, "Compiled browser-shell.merkava", 0.62f, 0.78f, 1.0f);
  awts_draw_text(state, -0.84f, 0.460f, "Type a URL or file path in the address bar, then press Enter.", 0.70f, 0.76f, 0.86f);

  awts_gl_rect(-0.64f, -0.35f, 1.28f, 0.58f, 0.015f, 0.035f, 0.070f);
  awts_gl_outline(-0.64f, -0.35f, 1.28f, 0.58f, 0.25f, 0.55f, 0.88f);
  awts_draw_text(state, -0.60f, 0.170f, "<canvas id=stage> WebGL bridge", 0.50f, 0.85f, 1.0f);

  awts_gl_triangle(0.0f, -0.05f, 0.26f, pulse);

  awts_gl_rect(-0.28f, -0.57f, 0.22f, 0.085f, 0.14f, 0.30f, 0.60f);
  awts_gl_outline(-0.28f, -0.57f, 0.22f, 0.085f, 0.55f, 0.78f, 1.0f);
  awts_draw_text(state, -0.255f, -0.535f, "GO", 0.86f, 0.93f, 1.0f);
  awts_gl_rect(0.02f, -0.57f, 0.62f, 0.085f, 0.08f, 0.12f, 0.18f);
  awts_gl_outline(0.02f, -0.57f, 0.62f, 0.085f, 0.35f, 0.50f, 0.72f);
  awts_draw_text(state, 0.045f, -0.535f, state->statusText, 0.78f, 0.86f, 1.0f);

  awts_gl_bar(-0.82f, -0.74f, 0.45f, state->webgl.viewport ? 1.0f : 0.08f, 0.35f, 0.65f, 1.0f);
  awts_gl_bar(-0.28f, -0.74f, 0.45f, state->webgl.clearColor ? 1.0f : 0.08f, 0.30f, 0.95f, 0.55f);
  awts_gl_bar(0.26f, -0.74f, 0.45f, state->webgl.drawArrays ? 1.0f : 0.08f, 1.0f, 0.55f, 0.30f);
  awts_draw_text(state, -0.82f, -0.795f, "viewport", 0.58f, 0.72f, 1.0f);
  awts_draw_text(state, -0.28f, -0.795f, "clearColor", 0.58f, 1.0f, 0.76f);
  awts_draw_text(state, 0.26f, -0.795f, "drawArrays", 1.0f, 0.70f, 0.52f);
}
